export class GraphClient { 
  constructor({getToken,fetcher=globalThis.fetch.bind(globalThis),sleep=ms=>new Promise(r=>setTimeout(r,ms))}) { this.getToken=getToken;this.fetcher=fetcher;this.sleep=sleep;this.requests=0; } 
  safeUrl(path) { 
    const url=new URL(path.startsWith('https:')?path:GRAPH+path); 
    ensure(url.origin==='https://graph.microsoft.com' && !url.username && !url.password && url.pathname.startsWith('/v1.0/me/drive/'),'PATH','許可されていないGraph宛先です。'); 
    return url.href; 
  } 
  async request(path,options={}) { 
    const url=this.safeUrl(path); const method=options.method||'GET'; ensure(['GET','POST','PUT'].includes(method),'METHOD','削除や未定義の通信は禁止しています。'); 
    for(let attempt=0;attempt<3;attempt++) { 
      let token;try{token=await this.getToken();}catch{throw new LabError('AUTH','Microsoftへの再接続が必要です。端末保存は保持しています。');} 
      let response; try { ensure(typeof token==='string'&&token,'AUTH','再接続が必要です。'); this.requests++; response=await this.fetcher(url,{...options,method,headers:{...(options.headers||{}),Authorization:`Bearer ${token}`},credentials:'omit',cache:'no-store',redirect:'error',signal:AbortSignal.timeout(25000)}); } catch(error) { if(error instanceof LabError)throw error; throw new LabError('NETWORK','通信が完了しませんでした。端末保存は保持しています。'); } 
      if([429,503].includes(response.status)&&attempt<2) { const wait=retryDelay(response.headers.get('Retry-After')); if(wait>60000)throw new LabError('RATE_LIMIT','通信回数の制限中です。時間を置いて同期してください。'); await this.sleep(Math.max(500,wait));continue; } 
      if(response.status===404)return null; 
      if(!response.ok) { const codes={401:'AUTH',403:'PERMISSION',409:'CONFLICT',412:'CONFLICT',429:'RATE_LIMIT',507:'QUOTA'}; throw new LabError(codes[response.status]||'GRAPH',`OneDriveへの${method==='GET'?'読込':'保存'}に失敗しました（${response.status}）。端末の変更は保持しています。`); } 
      if(response.status===204)return {}; 
      const raw=await response.text();ensure(byteLength(raw)<=8*LIMIT,'LIMIT','Graph応答が検証版の上限を超えています。'); 
      try{return JSON.parse(raw);}catch{throw new LabError('CORRUPT','Graph応答を読み取れません。');} 
    } 
    throw new LabError('RATE_LIMIT','OneDriveが混雑しています。後で同期してください。'); 
  } 
  async children(id) { 
    const result=[];let path=`/me/drive/items/${encodeURIComponent(id)}/children`;const visited=new Set(); 
    while(path) { ensure(!visited.has(path)&&visited.size<100,'LIMIT','一覧取得のページングが異常です。');visited.add(path);const page=await this.request(path);ensure(page&&Array.isArray(page.value),'CLOUD_MISSING','同期フォルダを取得できません。');result.push(...page.value);ensure(result.length<=10000,'LIMIT','検証版のファイル件数上限です。');path=page['@odata.nextLink']||null; } 
    return result; 
  } 
  async readText(item) { 
    ensure(item?.id,'MISSING','ファイルIDがありません。'); const meta=await this.request(`/me/drive/items/${encodeURIComponent(item.id)}`);ensure(meta,'CLOUD_MISSING','ファイルが見つかりません。'); 
    ensure(!Number.isFinite(meta.size)||meta.size<=LIMIT,'LIMIT','この検証版で扱うファイルは2MiB以下です。');const target=meta['@microsoft.graph.downloadUrl']; 
    ensure(typeof target==='string','DOWNLOAD','ダウンロード先を取得できません。');const url=new URL(target);ensure(url.protocol==='https:'&&!url.username&&!url.password,'PATH','安全なダウンロード先ではありません。'); 
    let response;try{response=await this.fetcher(url.href,{credentials:'omit',cache:'no-store',referrerPolicy:'no-referrer',signal:AbortSignal.timeout(25000)});}catch{throw new LabError('NETWORK','ファイル取得が中断しました。再同期してください。');} 
    ensure(response.ok,'DOWNLOAD','ファイル取得に失敗しました。');const raw=await response.text();ensure(byteLength(raw)<=LIMIT,'LIMIT','受信ファイルが大きすぎます。');return raw; 
  } 
}
